cat > /tmp/JspMigrationPlanTest.java <<'EOF'
package gg.jte.convert.jsp;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.net.MalformedURLException;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class JspMigrationPlanTest {
    @TempDir
    Path tempDir;

    @Test
    void plansAndCommitsDependenciesInDeterministicOrder() throws Exception {
        Path jspRoot = Files.createDirectories(tempDir.resolve("jsp"));
        Path jteRoot = tempDir.resolve("jte");
        Path tags = Files.createDirectories(jspRoot.resolve("my"));
        Path dependency = write(tags.resolve("dependency.tag"), "dependency");
        Path parent = write(tags.resolve("parent.tag"), "<%@ taglib tagdir=\"/my\" prefix=\"my\" %><my:dependency/>");
        Path usage = write(jspRoot.resolve("usage.jsp"), "<%@ taglib tagdir=\"/my\" prefix=\"my\" %><my:parent/>");
        AtomicInteger setupCalls = new AtomicInteger();

        JspMigrationPlan plan = converter(jspRoot, jteRoot).planTags(
                List.of("my/parent.tag", "my/dependency.tag"), converter -> setupCalls.incrementAndGet());

        assertThat(setupCalls).hasValue(2);
        assertThat(plan.getConversionOrder()).containsExactly(dependency, parent);
        assertThat(plan.getDeletes()).containsExactly(dependency, parent);
        assertThat(plan.getWrites().keySet()).contains(jteRoot.resolve("myDependency.jte").toAbsolutePath().normalize(),
                jteRoot.resolve("myParent.jte").toAbsolutePath().normalize(), usage.toAbsolutePath().normalize());
        assertThat(Files.exists(jteRoot)).isFalse();
        assertThat(Files.exists(dependency)).isTrue();

        plan.commit();

        assertThat(dependency).doesNotExist();
        assertThat(parent).doesNotExist();
        assertThat(usage).content().contains("<my:jte jte=\"myParent.jte\"/>");
        assertThat(jteRoot.resolve("myParent.jte")).content().contains("@template.myDependency()");
        assertThatThrownBy(plan::commit).isInstanceOf(IllegalStateException.class);
    }

    @Test
    void reportsAllStalePathsBeforeMutating() throws Exception {
        Path jspRoot = Files.createDirectories(tempDir.resolve("jsp"));
        Path jteRoot = tempDir.resolve("jte");
        Path selected = write(jspRoot.resolve("simple.tag"), "before");
        Path usage = write(jspRoot.resolve("usage.jsp"), "unchanged");
        JspMigrationPlan plan = converter(jspRoot, jteRoot).planTags(List.of("simple.tag"), null);
        write(selected, "after");
        write(usage, "changed");

        assertThatThrownBy(plan::commit)
                .isInstanceOfSatisfying(StaleJspMigrationPlanException.class, failure ->
                        assertThat(failure.getChangedPaths()).containsExactly(selected, usage));
        assertThat(jteRoot).doesNotExist();
        assertThat(selected).exists();
    }

    @Test
    void rollsBackMutationsAndCreatedDirectories() throws Exception {
        Path jspRoot = Files.createDirectories(tempDir.resolve("jsp"));
        Path jteRoot = tempDir.resolve("jte");
        Path first = write(jspRoot.resolve("first.tag"), "first");
        Path second = write(jspRoot.resolve("second.tag"), "second");
        AtomicInteger writes = new AtomicInteger();
        JspToJteConverter converter = new TestConverter(jspRoot, jteRoot) {
            @Override
            protected void writeMigrationFile(Path path, byte[] content) throws IOException {
                if (writes.incrementAndGet() == 2) {
                    throw new IOException("planned failure");
                }
                super.writeMigrationFile(path, content);
            }
        };
        JspMigrationPlan plan = converter.planTags(List.of("first.tag", "second.tag"), null);

        assertThatThrownBy(plan::commit).isInstanceOf(IOException.class).hasMessage("planned failure");
        assertThat(first).content().isEqualTo("first");
        assertThat(second).content().isEqualTo("second");
        assertThat(jteRoot).doesNotExist();
    }

    @Test
    void rejectsCyclesWithClosedDeterministicPath() throws Exception {
        Path jspRoot = Files.createDirectories(tempDir.resolve("jsp"));
        Path tags = Files.createDirectories(jspRoot.resolve("my"));
        write(tags.resolve("a.tag"), "<%@ taglib tagdir=\"/my\" prefix=\"my\" %><my:b/>");
        write(tags.resolve("b.tag"), "<%@ taglib tagdir=\"/my\" prefix=\"my\" %><my:a/>");

        assertThatThrownBy(() -> converter(jspRoot, tempDir.resolve("jte")).planTags(List.of("my/b.tag", "my/a.tag"), null))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("my/a.tag -> my/b.tag -> my/a.tag");
    }

    private JspToJteConverter converter(Path jspRoot, Path jteRoot) {
        return new TestConverter(jspRoot, jteRoot);
    }

    private Path write(Path path, String content) throws IOException {
        Files.createDirectories(path.getParent());
        Files.write(path, content.getBytes(StandardCharsets.UTF_8));
        return path.toAbsolutePath().normalize();
    }

    private static class TestConverter extends JspToJteConverter {
        private final Path jspRoot;

        private TestConverter(Path jspRoot, Path jteRoot) {
            super(jspRoot, jteRoot, "my:jte");
            this.jspRoot = jspRoot;
        }

        @Override
        protected URL getResourceBase() {
            try {
                return jspRoot.toUri().toURL();
            } catch (MalformedURLException failure) {
                throw new IllegalStateException(failure);
            }
        }
    }
}
